static bool ts_lex_keywords(TSLexer *lexer, TSStateId state) {
  START_LEXER();
  eof = lexer->eof(lexer);
  switch (state) {
    case 0:
      if (('A' <= lookahead && lookahead <= 'Z')) ADVANCE(1);
      END_STATE();
    case 1:
      ACCEPT_TOKEN(sym_function_identifier);
      if (lookahead == '-' ||
          ('0' <= lookahead && lookahead <= '9') ||
          ('A' <= lookahead && lookahead <= 'Z') ||
          lookahead == '_') ADVANCE(1);
      END_STATE();
    default:
      return false;
  }
}

